136	        for (Claim claim : sheetClaims) {
137	            Person person = personOf.get(claim.getPersonId());
138	            if (person == null || !person.countsAtEnd(claim, to, today) || claim.isDeferredOn(today) || claim.getDueBy().isBefore(from) || claim.getDueBy().isAfter(to)) {
139	                continue;
140	            }
141	            BigDecimal due = dueOf(claim, person.gradeOn(claim.getDate()), sheetRates, sheet, sheetClaims);
142	            if (due != null) {
143	                totals.merge(person.getId(), due, BigDecimal::add);
144	            }
145	        }
146	        return totals;
147	    }
148	
149	    /** What a candidate rate would change: how many claims would show a different due, and the sum of the
150	     *  differences (new due minus current due), with two decimals. */
151	    public record RatePreview(int count, String diff) {
152	    }
153	
154	    /** How the OPEN and PENDING claims of people on a grade (in force on each claim's date) would change were a rate
155	     *  to apply to that grade on every date: a claim bound by a statement does not change and a settled one is not
156	     *  counted; a due of none counts as 0 in the sum. Nothing is stored. */
157	    public RatePreview preview(String sheetId, String grade, BigDecimal rate) {
158	        RateChain sheetRates = rates.of(sheetId);
159	        RateChain candidate = sheetRates.withOwn(Stream.concat(
160	                sheetRates.levels().get(0).stream().filter(r -> !r.getGrade().equals(grade)),
161	                Stream.of(new Rate(sheetId, grade, null, rate.setScale(2, RoundingMode.UNNECESSARY)))).toList());
162	        Sheet sheet = sheets.findById(sheetId).orElse(null);
163	        Map<Long, Person> personOf = new LinkedHashMap<>();
164	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> personOf.put(p.getId(), p));
165	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
166	        int count = 0;
167	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
168	        for (Claim claim : sheetClaims) {
169	            Person person = personOf.get(claim.getPersonId());
170	            if (person == null || claim.getSettledDue() != null
171	                    || (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING)
172	                    || !grade.equals(person.gradeOn(claim.getDate()))) {
173	                continue;
174	            }
175	            BigDecimal now = dueOf(claim, grade, sheetRates, sheet, sheetClaims);
176	            BigDecimal then = dueOf(claim, grade, candidate, sheet, sheetClaims);
177	            if (!Objects.equals(now, then)) {
178	                count++;
179	                diff = diff.add(then == null ? BigDecimal.ZERO : then)
180	                        .subtract(now == null ? BigDecimal.ZERO : now);
181	            }
182	        }
183	        return new RatePreview(count, diff.setScale(2).toPlainString());
184	    }
185	
186	    /**
187	     * Record, once the change commits, how the sheet's figures moved since {@code before}: a ROLLUP line
188	     * for each person whose figures changed (one who did not exist before counting as changed), then a
189	     * TOTALS line if the sheet's totals changed. Nothing is recorded when no figure moved.
190	     */
191	    public void recordChanges(String sheetId, String user, Figures before) {
192	        Figures after = of(sheetId);
193	        after.people().forEach((id, figures) -> {
194	            PersonFigures was = before.people().get(id);
195	            if (was == null || !was.claimed().equals(figures.claimed()) || !was.dueTotal().equals(figures.dueTotal())
196	                    || !was.overdueTotal().equals(figures.overdueTotal())) {
197	                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
198	                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal()
199	                        + " overdue-total=" + figures.overdueTotal());
200	            }
201	        });
202	        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
203	                || !before.overdueTotal().equals(after.overdueTotal())) {
204	            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
205	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
206	        }
207	    }
208	
209	    /** A claim's due: its settled figure, else its stated one (none while PENDING), else its amount at the rate in force on its date of
210	     *  its person's grade in force on that date (the sheet's own, else its nearest ancestor's), rounded as the claim rounds (by the sheet's policy date); an overdue claim's late charge is added on top of the figure, and the
211	     *  sum is raised to the floor in force on its date unless it is a correction. */
212	    private static BigDecimal dueOf(Claim claim, String grade, RateChain sheetRates, Sheet sheet, List<Claim> sheetClaims) {
213	        if (claim.getSettledDue() != null) {
214	            return claim.getSettledDue();
215	        }
216	        RoundingMode rounding = sheet == null ? RoundingMode.HALF_EVEN
217	                : sheet.roundingFor(ClaimService.roundingDate(claim, sheetClaims));
218	        BigDecimal figure = claim.isBound() ? claim.getBoundDue()
219	                : sheetRates.inForceOn(grade, claim.getDate())
220	                        .map(rate -> ClaimService.liveFigure(claim, rate.getRate(), rounding))
221	                        .orElse(null);
222	        return figure == null || sheet == null ? figure
223	                : ClaimService.floored(claim, figure.add(ClaimService.lateCharge(claim, figure, sheet, grade)), sheet);
224	    }
225	}
