252	/** What a sheet held at a moment. As far as a person's figures depend on it (its dated settings and policy date, its
253	 *  rates, its people and its claims) each part is rebuilt as an unsaved entity, so the figures of the sheet as it
254	 *  stood then are worked out by the same rules as the live ones. Alongside, the rest of what the screen shows of it,
255	 *  as the screen reads it: its other settings, and each list the screen reads (see {@link Views}). */
256	public record SheetState(List<SettingState> settings, LocalDate policyDate, List<RateState> rates,
257	        List<PersonState> people, List<ClaimState> claims, Map<String, String> permissions,
258	        LocalDate periodNumberingFrom, Integer graceDays, boolean archived, Views views, LocalDate entryDate,
259	        Integer lastSettleBatch, BigDecimal pot) {
260	
261	    /** Each list the screen reads of the sheet, as it read it then; a person's grade there is the one in force on the
262	     *  sheet's today then (see {@link #people(LocalDate)} for it on another day). */
263	    public record Views(List<PersonView> people, List<ClaimView> claims, List<RateView> rates,
264	            List<PeriodView> periods, List<SummaryView> statements, List<PatronView> patrons,
265	            Map<String, List<Long>> watches, List<RoleView> roles, List<DelegationView> delegations,
266	            List<HolidayView> holidays) {
267	
268	        /** Nothing: a sheet as it stood before any change was made on it. */
269	        public static final Views NONE = new Views(List.of(), List.of(), List.of(), List.of(), List.of(), List.of(),
270	                Map.of(), List.of(), List.of(), List.of());
271	    }
272	
273	    public record SettingState(String key, LocalDate from, String value) {
274	    }
