277	    }
278	
279	    public record GradeState(LocalDate from, String grade) {
280	    }
281	
282	    public record HoldState(LocalDate from, LocalDate to) {
283	    }
284	
285	    public record RetirementState(LocalDate from, LocalDate to) {
286	    }
