288	    public record PersonState(long id, String name, List<GradeState> grades, Integer terms, LocalDate retiredFrom,
289	            List<HoldState> holds, List<RetirementState> pastRetirements) {
290	
291	        /** The person as they stood then, unsaved. */
292	        public Person rebuild(String sheetId) {
293	            Person person = new Person(sheetId, name, grades.get(0).grade());
294	            grades.stream().skip(1).forEach(g -> person.setGradeFrom(g.from(), g.grade()));
295	            person.setTerms(terms);
296	            person.setRetiredFrom(retiredFrom);
297	            holds.forEach(h -> person.addHold(new Hold(h.from(), h.to())));
298	            if (pastRetirements != null) {
299	                pastRetirements.forEach(r -> person.addPastRetirement(new PastRetirement(r.from(), r.to())));
300	            }
301	            return person;
302	        }
303	    }
304	
305	    public record ClaimState(long id, long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, String note,
306	            String corrects, long listed, ClaimStatus status, String number, BigDecimal settledDue, boolean stated,
307	            BigDecimal statedDue, LocalDate deferredUntil, LocalDate remindedOn, String ref, String tags) {
308	
309	        /** The claim as it stood then, unsaved. */
310	        public Claim rebuild(String sheetId) {
311	            Claim claim = new Claim(sheetId, personId, amount, date, dueBy, note, corrects, listed);
312	            claim.setStatus(status);
313	            claim.setNumber(number);
314	            claim.setSettledDue(settledDue);
315	            claim.setDeferredUntil(deferredUntil);
316	            claim.remind(remindedOn);
317	            claim.setRef(ref);
318	            claim.setTags(tags);
319	            if (stated) {
320	                claim.bind(statedDue);
321	            }
322	            return claim;
323	        }
324	    }
325	
326	    /** What the sheet holds now. */
327	    public static SheetState of(Sheet sheet, List<Rate> rates, List<Person> people, List<Claim> claims, Views views) {
328	        return new SheetState(
329	                sheet.getSettings().stream().map(s -> new SettingState(s.getKey(), s.getFrom(), s.getValue())).toList(),
330	                sheet.getPolicyDate(),
331	                rates.stream().map(r -> new RateState(r.getGrade(), r.getFromDate(), r.getToDate(), r.getRate())).toList(),
332	                people.stream().map(SheetState::stateOf).toList(),
333	                claims.stream().map(c -> new ClaimState(c.getId(), c.getPersonId(), c.getAmount(), c.getDate(),
334	                        c.getDueBy(), c.getNote(), c.getCorrects(), c.getListed(), c.getStatus(), c.getNumber(),
335	                        c.getSettledDue(), c.isStated(), c.getStatedDue(), c.getDeferredUntil(), c.getRemindedOn(), c.getRef(), c.getTags())).toList(),
336	                new TreeMap<>(sheet.getPermissions()), sheet.getPeriodNumberingFrom(), sheet.getGraceDays(),
337	                sheet.isArchived(), views, sheet.getEntryDate(), sheet.getLastSettleBatch(),
338	                sheet.getPot());
339	    }
340	
341	    /** The people as the screen read them then, each with the grade in force on {@code today}. */
342	    public List<PersonView> people(String sheetId, LocalDate today) {
343	        return views.people().stream().map(v -> person(v.id())
344	                .map(p -> new PersonView(v.id(), v.name(), p.rebuild(sheetId).gradeOn(today), v.grades(), v.terms(),
345	                        v.version(), v.retired(), v.retiredFrom(), v.held(), v.holds(), v.contact(), v.aliases(), v.clashing(), v.origin(),
346	                        v.pastRetirements()))
347	                .orElse(v)).toList();
348	    }
349	
350	    private static PersonState stateOf(Person p) {
351	        List<GradeFrom> grades = p.getGrades();
352	        return new PersonState(p.getId(), p.getName(),
353	                grades.stream().map(g -> new GradeState(g.getFromDate(), g.getGrade())).toList(), p.getTerms(),
354	                p.getRetiredFrom(), p.getHolds().stream().map(h -> new HoldState(h.getFromDate(), h.getToDate())).toList(),
355	                p.getPastRetirements().stream().map(r -> new RetirementState(r.getFromDate(), r.getToDate())).toList());
356	    }
357	
358	    /** The sheet as it stood then, unsaved, with {@code today} standing in for its today. */
359	    public Sheet rebuildSheet(Sheet live, LocalDate today) {
360	        Sheet sheet = new Sheet(live.getId(), live.getCreatedBy(), live.getCreatedAt(), today);
361	        settings.forEach(s -> sheet.record(s.key(), s.from(), s.value()));
362	        sheet.setPolicyDate(policyDate);
363	        if (permissions != null) {
364	            permissions.forEach(sheet::setPermission);
365	        }
366	        sheet.setPeriodNumberingFrom(periodNumberingFrom);
367	        sheet.setGraceDays(graceDays);
368	        sheet.setEntryDate(entryDate);
369	        sheet.setPot(pot);
370	        // The parent is not dated: it is the one the sheet names now.
371	        sheet.setParentId(live.getParentId());
372	        if (lastSettleBatch != null) {
373	            sheet.setLastSettleBatch(lastSettleBatch);
374	        }
375	        if (archived) {
376	            sheet.archive();
377	        }
378	        return sheet;
379	    }
380	
381	    /** The rates as they stood then, unsaved. */
382	    public List<Rate> rebuildRates(String sheetId) {
383	        return rates.stream().map(r -> {
384	            Rate rate = new Rate(sheetId, r.grade(), r.from(), r.rate());
385	            rate.setToDate(r.to());
386	            return rate;
387	        }).toList();
388	    }
389	
390	    /** The person with this id as they stood then; empty when they were not on the sheet yet. */
391	    public Optional<PersonState> person(long id) {
392	        return people.stream().filter(p -> p.id() == id).findFirst();
393	    }
394	}
