435	/**
436	 * A sheet's history: after each change, what the sheet holds is kept under the sheet's today, replacing what was kept
437	 * under that day before. The sheet as it stood at the end of a date is then the last kept under a day on or before
438	 * it: every change made while the sheet's today was on or before that date, and none made later.
439	 */
440	@Service
441	public class SheetHistory {
442	
443	    /** The request header naming the date a user's screen shows the sheet as of (an ISO date): while it is sent, every
444	     *  read of the sheet answers as the sheet stood at the end of that date, that date standing in for its today, and
445	     *  every change is refused (see {@link AsOfGuard}). */
446	    public static final String AS_OF_HEADER = "X-As-Of";
447	
448	    private final SheetSnapshotRepository snapshots;
449	    private final SheetRepository sheets;
450	    private final RateRepository rates;
451	    private final PersonRepository people;
452	    private final ClaimRepository claims;
453	    private final PeriodRepository periods;
454	    private final StatementRepository statements;
455	    private final PatronRepository patrons;
456	    private final WatchRepository watches;
457	    private final RoleRepository roles;
458	    private final DelegationRepository delegations;
459	    private final HolidayRepository holidays;
460	    private final JsonMapper json;
461	
462	    public SheetHistory(SheetSnapshotRepository snapshots, SheetRepository sheets, RateRepository rates,
463	            PersonRepository people, ClaimRepository claims, PeriodRepository periods, StatementRepository statements,
464	            PatronRepository patrons, WatchRepository watches, RoleRepository roles, DelegationRepository delegations,
465	            HolidayRepository holidays, JsonMapper json) {
466	        this.snapshots = snapshots;
467	        this.sheets = sheets;
468	        this.rates = rates;
469	        this.people = people;
470	        this.claims = claims;
471	        this.periods = periods;
472	        this.statements = statements;
473	        this.patrons = patrons;
474	        this.watches = watches;
475	        this.roles = roles;
476	        this.delegations = delegations;
477	        this.holidays = holidays;
478	        this.json = json;
479	    }
480	
481	    /** Keep what the sheet holds once the change being made is done: just before the current transaction commits,
482	     *  once however many changes it records; outside a transaction, at once. */
483	    public void keepOnCommit(String sheetId) {
484	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
485	            keep(sheetId);
486	            return;
487	        }
488	        String key = SheetHistory.class.getName() + ":" + sheetId;
489	        if (TransactionSynchronizationManager.hasResource(key)) {
490	            return;
491	        }
492	        TransactionSynchronizationManager.bindResource(key, Boolean.TRUE);
493	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
494	            @Override
495	            public void beforeCommit(boolean readOnly) {
496	                if (!readOnly) {
497	                    keep(sheetId);
498	                }
499	            }
500	
501	            @Override
502	            public void afterCompletion(int status) {
503	                TransactionSynchronizationManager.unbindResourceIfPossible(key);
504	            }
505	        });
506	    }
507	
508	    /** Keep what the sheet holds now under its today. */
509	    @Transactional
510	    public void keep(String sheetId) {
511	        Sheet sheet = sheets.findById(sheetId).orElse(null);
512	        if (sheet == null) {
513	            return;
514	        }
515	        List<Rate> sheetRates = rates.findBySheetId(sheetId);
516	        List<Person> sheetPeople = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
517	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
518	        Map<String, List<Long>> watched = new TreeMap<>();
519	        watches.findBySheetIdOrderByIdAsc(sheetId).forEach(w ->
520	                watched.computeIfAbsent(w.getUserName(), u -> new ArrayList<>()).add(w.getPersonId()));
521	        SheetState.Views views = new SheetState.Views(
522	                sheetPeople.stream().map(p -> PersonView.of(p, sheet.getToday())).toList(),
523	                sheetClaims.stream().map(ClaimView::of).map(SheetHistory::unlocked).toList(),
524	                sheetRates.stream().sorted(Comparator.comparing(Rate::getGrade).thenComparing(Rate.BY_FROM))
525	                        .map(RateView::of).toList(),
526	                periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().map(PeriodView::of).toList(),
527	                StatementService.summarize(statements.findBySheetIdOrderByIdAsc(sheetId)).stream()
528	                        .map(SummaryView::of).toList(),
529	                patrons.findBySheetIdOrderByIdAsc(sheetId).stream().map(PatronView::of).toList(),
530	                watched,
531	                roles.findBySheetIdOrderByUserName(sheetId).stream().map(RoleView::of).toList(),
532	                delegations.findBySheetIdOrderByIdAsc(sheetId).stream().map(DelegationView::of).toList(),
533	                holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(HolidayView::of).toList());
534	        SheetState state = SheetState.of(sheet, sheetRates, sheetPeople, sheetClaims, views);
535	        snapshots.deleteBySheetIdAndAsOf(sheetId, sheet.getToday());
536	        snapshots.saveAndFlush(new SheetSnapshot(sheetId, sheet.getToday(), json.writeValueAsString(state)));
537	    }
538	
539	    /** The sheet as it stood at the end of a date; empty when no change was made on it by then. */
540	    @Transactional(readOnly = true)
541	    public Optional<SheetState> asOf(String sheetId, LocalDate date) {
542	        return snapshots.findFirstBySheetIdAndAsOfLessThanEqualOrderByAsOfDescIdDesc(sheetId, date)
543	                .map(s -> json.readValue(s.getState(), SheetState.class));
544	    }
545	
546	    /** The claim as kept: no one's editor lock is part of what the sheet held. */
547	    private static ClaimView unlocked(ClaimView c) {
548	        return new ClaimView(c.id(), c.personId(), c.amount(), c.date(), c.note(), c.status(), c.number(),
549	                c.settledDue(), c.openedBy(), c.stated(), c.statedDue(), c.corrects(), c.dueBy(), c.deferredUntil(),
550	                c.log(), c.proofs(), c.splitFrom(), null, c.lateEntry(), c.remindedOn(), c.ref(), c.tags(),
551	                c.voidReason(), c.comments(), c.editedBy(), c.batch());
552	    }
553	
554	    /** The lists the screen reads of the sheet as it stood at the end of a date; none when no change was made on it
555	     *  by then. */
556	    @Transactional(readOnly = true)
557	    public SheetState.Views viewsAsOf(String sheetId, LocalDate date) {
558	        return asOf(sheetId, date).map(SheetState::views).orElse(SheetState.Views.NONE);
559	    }
560	
561	    /** The people as the screen read them at the end of a date, each with the grade in force on it. */
562	    @Transactional(readOnly = true)
563	    public List<PersonView> peopleAsOf(String sheetId, LocalDate date) {
564	        return asOf(sheetId, date).map(s -> s.people(sheetId, date)).orElse(List.of());
565	    }
566	
567	    /** The sheet as it stood at the end of a date, unsaved, with that date standing in for its today: as it was
568	     *  started when no change was made on it by then. Its parent, not dated, is the one it names now. */
569	    @Transactional(readOnly = true)
570	    public Sheet sheetAsOf(Sheet live, LocalDate date) {
571	        return asOf(live.getId(), date).map(s -> s.rebuildSheet(live, date))
572	                .orElseGet(() -> {
573	                    Sheet started = new Sheet(live.getId(), live.getCreatedBy(), live.getCreatedAt(), date);
574	                    started.setParentId(live.getParentId());
575	                    return started;
576	                });
577	    }
578	}
