import net.officefloor.hq.app.rate.RateChain;
import net.officefloor.hq.app.rate.RateChains;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The figures of a sheet as the screen shows them: each person's claimed, due-total and overdue-total, and the
 * sheet's claimed-total, due-total and overdue-total (the latter two trimmed of the single highest and lowest
 * person's figure when three or more people have one). A change takes the figures before it and, once made, records
 * a ROLLUP line for each person whose figures moved and a TOTALS line when any of the sheet's totals moved.
 */
@Service
public class Rollup {

    /** A person's figures: claimed, due-total and overdue-total, each with two decimals; due-total is "n/a" when they
     *  have none. */
    public record PersonFigures(String name, String claimed, String dueTotal, String overdueTotal) {
    }

    /** A sheet's figures: each person's, by id in the order they were added, and the sheet's totals. */
    public record Figures(Map<Long, PersonFigures> people, String claimedTotal, String dueTotal, String overdueTotal) {
    }

    private static final String NOT_AVAILABLE = "n/a";

    private final SheetRepository sheets;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateChains rates;
    private final Audit audit;

    public Rollup(SheetRepository sheets, PersonRepository people, ClaimRepository claims, RateChains rates,
            Audit audit) {
        this.sheets = sheets;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now. */
    public Figures of(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        RateChain sheetRates = rates.of(sheetId);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
        Map<Long, PersonFigures> byPerson = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        List<BigDecimal> dueFigures = new ArrayList<>();
        List<BigDecimal> overdueFigures = new ArrayList<>();
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            List<Claim> counting = sheetClaims.stream()
                    .filter(c -> c.getPersonId().equals(person.getId()) && person.counts(c, today)
                            && !c.isDeferredOn(today))
                    .toList();
            BigDecimal claimed = counting.stream().map(Claim::getAmount)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            claimedTotal = claimedTotal.add(claimed);
            // As on screen: with no rate in force today for their grade on the sheet's today, nor for the grade
            // any of their claims is at, and no claim that has a due, the person has no due-total.
            List<BigDecimal> dues = counting.stream()
                    .map(c -> dueOf(c, person.gradeOn(c.getDate()), sheetRates, sheet, sheetClaims))
                    .filter(Objects::nonNull)
                    .toList();
            boolean anyRate = today != null && Stream.concat(Stream.of(person.gradeOn(today)),
                            counting.stream().map(c -> person.gradeOn(c.getDate())))
                    .anyMatch(grade -> sheetRates.inForceOn(grade, today).isPresent());
            String due = NOT_AVAILABLE;
            if (!dues.isEmpty() || anyRate) {
                BigDecimal sum = dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
                BigDecimal total = sheet == null ? sum : sheet.capped(sum);
                dueFigures.add(total);
                due = total.toPlainString();
            }
            // As on screen: the dues of the claims that count which are open and due by (plus their grade's grace
            // days) a day before the sheet's today.
            BigDecimal overdue = counting.stream()
                    .filter(c -> today != null && ClaimService.isOverdue(c, sheet, person.gradeOn(c.getDate())))
                    .map(c -> dueOf(c, person.gradeOn(c.getDate()), sheetRates, sheet, sheetClaims))
                    .filter(Objects::nonNull)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            overdueFigures.add(overdue);
            byPerson.put(person.getId(),
                    new PersonFigures(person.getName(), claimed.toPlainString(), due, overdue.toPlainString()));
        }
        return new Figures(byPerson, claimedTotal.toPlainString(), trimmedSum(dueFigures).toPlainString(),
                trimmedSum(overdueFigures).toPlainString());
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
    static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        if (figures.size() < 3) {
            return sum;
        }
        BigDecimal highest = figures.stream().max(BigDecimal::compareTo).orElseThrow();
        BigDecimal lowest = figures.stream().min(BigDecimal::compareTo).orElseThrow();
        return sum.subtract(highest).subtract(lowest);
    }

    /** Each person's due-total for the dates from {@code from} to {@code to} inclusive, by person id, as the screen
     *  shows a person's period figure: the dues as shown now of their claims that counted by the status they had at the end
     *  of {@code to} (a held person's open ones dated within a
     *  hold and not stated do not) due by in it, none counting as 0; every person on the sheet has one. */
    public Map<Long, BigDecimal> dueByPersonBetween(String sheetId, LocalDate from, LocalDate to) {
        RateChain sheetRates = rates.of(sheetId);
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        Map<Long, Person> personOf = new LinkedHashMap<>();
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> {
            personOf.put(p.getId(), p);
            totals.put(p.getId(), BigDecimal.ZERO.setScale(2));
        });
        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
        for (Claim claim : sheetClaims) {
            Person person = personOf.get(claim.getPersonId());
            if (person == null || !person.countsAtEnd(claim, to, today) || claim.isDeferredOn(today) || claim.getDueBy().isBefore(from) || claim.getDueBy().isAfter(to)) {
                continue;
            }
            BigDecimal due = dueOf(claim, person.gradeOn(claim.getDate()), sheetRates, sheet, sheetClaims);
            if (due != null) {
                totals.merge(person.getId(), due, BigDecimal::add);
            }
        }
        return totals;
    }

    /** What a candidate rate would change: how many claims would show a different due, and the sum of the
     *  differences (new due minus current due), with two decimals. */
    public record RatePreview(int count, String diff) {
    }

    /** How the OPEN and PENDING claims of people on a grade (in force on each claim's date) would change were a rate
     *  to apply to that grade on every date: a claim bound by a statement does not change and a settled one is not
     *  counted; a due of none counts as 0 in the sum. Nothing is stored. */
    public RatePreview preview(String sheetId, String grade, BigDecimal rate) {
        RateChain sheetRates = rates.of(sheetId);
        RateChain candidate = sheetRates.withOwn(Stream.concat(
                sheetRates.levels().get(0).stream().filter(r -> !r.getGrade().equals(grade)),
                Stream.of(new Rate(sheetId, grade, null, rate.setScale(2, RoundingMode.UNNECESSARY)))).toList());
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        Map<Long, Person> personOf = new LinkedHashMap<>();
        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> personOf.put(p.getId(), p));
        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
        int count = 0;
        BigDecimal diff = BigDecimal.ZERO.setScale(2);
        for (Claim claim : sheetClaims) {
            Person person = personOf.get(claim.getPersonId());
            if (person == null || claim.getSettledDue() != null
                    || (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING)
                    || !grade.equals(person.gradeOn(claim.getDate()))) {
                continue;
            }
            BigDecimal now = dueOf(claim, grade, sheetRates, sheet, sheetClaims);
            BigDecimal then = dueOf(claim, grade, candidate, sheet, sheetClaims);
            if (!Objects.equals(now, then)) {
                count++;
                diff = diff.add(then == null ? BigDecimal.ZERO : then)
                        .subtract(now == null ? BigDecimal.ZERO : now);
            }
        }
        return new RatePreview(count, diff.setScale(2).toPlainString());
    }

    /**
     * Record, once the change commits, how the sheet's figures moved since {@code before}: a ROLLUP line
     * for each person whose figures changed (one who did not exist before counting as changed), then a
     * TOTALS line if the sheet's totals changed. Nothing is recorded when no figure moved.
     */
    public void recordChanges(String sheetId, String user, Figures before) {
        Figures after = of(sheetId);
        after.people().forEach((id, figures) -> {
            PersonFigures was = before.people().get(id);
            if (was == null || !was.claimed().equals(figures.claimed()) || !was.dueTotal().equals(figures.dueTotal())
                    || !was.overdueTotal().equals(figures.overdueTotal())) {
                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal()
                        + " overdue-total=" + figures.overdueTotal());
            }
        });
        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
                || !before.overdueTotal().equals(after.overdueTotal())) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
        }
    }

    /** A claim's due: its settled figure, else its stated one (none while PENDING), else its amount at the rate in force on its date of
     *  its person's grade in force on that date (the sheet's own, else its nearest ancestor's), rounded as the claim rounds (by the sheet's policy date); an overdue claim's late charge is added on top of the figure, and the
     *  sum is raised to the floor in force on its date unless it is a correction. */
    private static BigDecimal dueOf(Claim claim, String grade, RateChain sheetRates, Sheet sheet, List<Claim> sheetClaims) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        RoundingMode rounding = sheet == null ? RoundingMode.HALF_EVEN
                : sheet.roundingFor(ClaimService.roundingDate(claim, sheetClaims));
        BigDecimal figure = claim.isBound() ? claim.getBoundDue()
                : sheetRates.inForceOn(grade, claim.getDate())
                        .map(rate -> ClaimService.liveFigure(claim, rate.getRate(), rounding))
                        .orElse(null);
        return figure == null || sheet == null ? figure
                : ClaimService.floored(claim, figure.add(ClaimService.lateCharge(claim, figure, sheet, grade)), sheet);
    }
}
package net.officefloor.hq.app.history;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.patron.PatronController.PatronView;
import net.officefloor.hq.app.period.PeriodController.PeriodView;
import net.officefloor.hq.app.person.PersonController.PersonView;
import net.officefloor.hq.app.rate.RateController.RateView;
import net.officefloor.hq.app.holiday.HolidayController.HolidayView;
import net.officefloor.hq.app.role.DelegationController.DelegationView;
import net.officefloor.hq.app.role.RoleController.RoleView;
import net.officefloor.hq.app.statement.StatementController.SummaryView;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.GradeFrom;
import net.officefloor.hq.app.person.Hold;
import net.officefloor.hq.app.person.PastRetirement;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.sheet.Sheet;

/** What a sheet held at a moment. As far as a person's figures depend on it (its dated settings and policy date, its
 *  rates, its people and its claims) each part is rebuilt as an unsaved entity, so the figures of the sheet as it
 *  stood then are worked out by the same rules as the live ones. Alongside, the rest of what the screen shows of it,
 *  as the screen reads it: its other settings, and each list the screen reads (see {@link Views}). */
public record SheetState(List<SettingState> settings, LocalDate policyDate, List<RateState> rates,
        List<PersonState> people, List<ClaimState> claims, Map<String, String> permissions,
        LocalDate periodNumberingFrom, Integer graceDays, boolean archived, Views views, LocalDate entryDate,
        Integer lastSettleBatch, BigDecimal pot) {

    /** Each list the screen reads of the sheet, as it read it then; a person's grade there is the one in force on the
     *  sheet's today then (see {@link #people(LocalDate)} for it on another day). */
    public record Views(List<PersonView> people, List<ClaimView> claims, List<RateView> rates,
            List<PeriodView> periods, List<SummaryView> statements, List<PatronView> patrons,
            Map<String, List<Long>> watches, List<RoleView> roles, List<DelegationView> delegations,
            List<HolidayView> holidays) {

        /** Nothing: a sheet as it stood before any change was made on it. */
        public static final Views NONE = new Views(List.of(), List.of(), List.of(), List.of(), List.of(), List.of(),
                Map.of(), List.of(), List.of(), List.of());
    }

    public record SettingState(String key, LocalDate from, String value) {
    }

    public record RateState(String grade, LocalDate from, LocalDate to, BigDecimal rate) {
    }

    public record GradeState(LocalDate from, String grade) {
    }

    public record HoldState(LocalDate from, LocalDate to) {
    }

    public record RetirementState(LocalDate from, LocalDate to) {
    }

    public record PersonState(long id, String name, List<GradeState> grades, Integer terms, LocalDate retiredFrom,
            List<HoldState> holds, List<RetirementState> pastRetirements) {

        /** The person as they stood then, unsaved. */
        public Person rebuild(String sheetId) {
            Person person = new Person(sheetId, name, grades.get(0).grade());
            grades.stream().skip(1).forEach(g -> person.setGradeFrom(g.from(), g.grade()));
            person.setTerms(terms);
            person.setRetiredFrom(retiredFrom);
            holds.forEach(h -> person.addHold(new Hold(h.from(), h.to())));
            if (pastRetirements != null) {
                pastRetirements.forEach(r -> person.addPastRetirement(new PastRetirement(r.from(), r.to())));
            }
            return person;
        }
    }

    public record ClaimState(long id, long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, String note,
            String corrects, long listed, ClaimStatus status, String number, BigDecimal settledDue, boolean stated,
            BigDecimal statedDue, LocalDate deferredUntil, LocalDate remindedOn, String ref, String tags) {

        /** The claim as it stood then, unsaved. */
        public Claim rebuild(String sheetId) {
            Claim claim = new Claim(sheetId, personId, amount, date, dueBy, note, corrects, listed);
            claim.setStatus(status);
            claim.setNumber(number);
            claim.setSettledDue(settledDue);
            claim.setDeferredUntil(deferredUntil);
            claim.remind(remindedOn);
            claim.setRef(ref);
            claim.setTags(tags);
            if (stated) {
                claim.bind(statedDue);
            }
            return claim;
        }
    }

    /** What the sheet holds now. */
    public static SheetState of(Sheet sheet, List<Rate> rates, List<Person> people, List<Claim> claims, Views views) {
        return new SheetState(
                sheet.getSettings().stream().map(s -> new SettingState(s.getKey(), s.getFrom(), s.getValue())).toList(),
                sheet.getPolicyDate(),
                rates.stream().map(r -> new RateState(r.getGrade(), r.getFromDate(), r.getToDate(), r.getRate())).toList(),
                people.stream().map(SheetState::stateOf).toList(),
                claims.stream().map(c -> new ClaimState(c.getId(), c.getPersonId(), c.getAmount(), c.getDate(),
                        c.getDueBy(), c.getNote(), c.getCorrects(), c.getListed(), c.getStatus(), c.getNumber(),
                        c.getSettledDue(), c.isStated(), c.getStatedDue(), c.getDeferredUntil(), c.getRemindedOn(), c.getRef(), c.getTags())).toList(),
                new TreeMap<>(sheet.getPermissions()), sheet.getPeriodNumberingFrom(), sheet.getGraceDays(),
                sheet.isArchived(), views, sheet.getEntryDate(), sheet.getLastSettleBatch(),
                sheet.getPot());
    }

    /** The people as the screen read them then, each with the grade in force on {@code today}. */
    public List<PersonView> people(String sheetId, LocalDate today) {
        return views.people().stream().map(v -> person(v.id())
                .map(p -> new PersonView(v.id(), v.name(), p.rebuild(sheetId).gradeOn(today), v.grades(), v.terms(),
                        v.version(), v.retired(), v.retiredFrom(), v.held(), v.holds(), v.contact(), v.aliases(), v.clashing(), v.origin(),
                        v.pastRetirements()))
                .orElse(v)).toList();
    }

    private static PersonState stateOf(Person p) {
        List<GradeFrom> grades = p.getGrades();
        return new PersonState(p.getId(), p.getName(),
                grades.stream().map(g -> new GradeState(g.getFromDate(), g.getGrade())).toList(), p.getTerms(),
                p.getRetiredFrom(), p.getHolds().stream().map(h -> new HoldState(h.getFromDate(), h.getToDate())).toList(),
                p.getPastRetirements().stream().map(r -> new RetirementState(r.getFromDate(), r.getToDate())).toList());
    }

    /** The sheet as it stood then, unsaved, with {@code today} standing in for its today. */
    public Sheet rebuildSheet(Sheet live, LocalDate today) {
        Sheet sheet = new Sheet(live.getId(), live.getCreatedBy(), live.getCreatedAt(), today);
        settings.forEach(s -> sheet.record(s.key(), s.from(), s.value()));
        sheet.setPolicyDate(policyDate);
        if (permissions != null) {
            permissions.forEach(sheet::setPermission);
        }
        sheet.setPeriodNumberingFrom(periodNumberingFrom);
        sheet.setGraceDays(graceDays);
        sheet.setEntryDate(entryDate);
        sheet.setPot(pot);
        // The parent is not dated: it is the one the sheet names now.
        sheet.setParentId(live.getParentId());
        if (lastSettleBatch != null) {
            sheet.setLastSettleBatch(lastSettleBatch);
        }
        if (archived) {
            sheet.archive();
        }
        return sheet;
    }

    /** The rates as they stood then, unsaved. */
    public List<Rate> rebuildRates(String sheetId) {
        return rates.stream().map(r -> {
            Rate rate = new Rate(sheetId, r.grade(), r.from(), r.rate());
            rate.setToDate(r.to());
            return rate;
        }).toList();
    }

    /** The person with this id as they stood then; empty when they were not on the sheet yet. */
    public Optional<PersonState> person(long id) {
        return people.stream().filter(p -> p.id() == id).findFirst();
    }
}
package net.officefloor.hq.app.history;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.Optional;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.patron.PatronController.PatronView;
import net.officefloor.hq.app.patron.PatronRepository;
import net.officefloor.hq.app.period.PeriodController.PeriodView;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonController.PersonView;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateController.RateView;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.holiday.HolidayController.HolidayView;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.role.DelegationController.DelegationView;
import net.officefloor.hq.app.role.DelegationRepository;
import net.officefloor.hq.app.role.RoleController.RoleView;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.statement.StatementController.SummaryView;
import net.officefloor.hq.app.statement.StatementRepository;
import net.officefloor.hq.app.statement.StatementService;
import net.officefloor.hq.app.watch.WatchRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import tools.jackson.databind.json.JsonMapper;

/**
 * A sheet's history: after each change, what the sheet holds is kept under the sheet's today, replacing what was kept
 * under that day before. The sheet as it stood at the end of a date is then the last kept under a day on or before
 * it: every change made while the sheet's today was on or before that date, and none made later.
 */
@Service
public class SheetHistory {

    /** The request header naming the date a user's screen shows the sheet as of (an ISO date): while it is sent, every
     *  read of the sheet answers as the sheet stood at the end of that date, that date standing in for its today, and
     *  every change is refused (see {@link AsOfGuard}). */
    public static final String AS_OF_HEADER = "X-As-Of";

    private final SheetSnapshotRepository snapshots;
    private final SheetRepository sheets;
    private final RateRepository rates;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final PeriodRepository periods;
    private final StatementRepository statements;
    private final PatronRepository patrons;
    private final WatchRepository watches;
    private final RoleRepository roles;
    private final DelegationRepository delegations;
    private final HolidayRepository holidays;
    private final JsonMapper json;

    public SheetHistory(SheetSnapshotRepository snapshots, SheetRepository sheets, RateRepository rates,
            PersonRepository people, ClaimRepository claims, PeriodRepository periods, StatementRepository statements,
            PatronRepository patrons, WatchRepository watches, RoleRepository roles, DelegationRepository delegations,
            HolidayRepository holidays, JsonMapper json) {
        this.snapshots = snapshots;
        this.sheets = sheets;
        this.rates = rates;
        this.people = people;
        this.claims = claims;
        this.periods = periods;
        this.statements = statements;
        this.patrons = patrons;
        this.watches = watches;
        this.roles = roles;
        this.delegations = delegations;
        this.holidays = holidays;
        this.json = json;
    }

    /** Keep what the sheet holds once the change being made is done: just before the current transaction commits,
     *  once however many changes it records; outside a transaction, at once. */
    public void keepOnCommit(String sheetId) {
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            keep(sheetId);
            return;
        }
        String key = SheetHistory.class.getName() + ":" + sheetId;
        if (TransactionSynchronizationManager.hasResource(key)) {
            return;
        }
        TransactionSynchronizationManager.bindResource(key, Boolean.TRUE);
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void beforeCommit(boolean readOnly) {
                if (!readOnly) {
                    keep(sheetId);
                }
            }

            @Override
            public void afterCompletion(int status) {
                TransactionSynchronizationManager.unbindResourceIfPossible(key);
            }
        });
    }

    /** Keep what the sheet holds now under its today. */
    @Transactional
    public void keep(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        if (sheet == null) {
            return;
        }
        List<Rate> sheetRates = rates.findBySheetId(sheetId);
        List<Person> sheetPeople = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
        Map<String, List<Long>> watched = new TreeMap<>();
        watches.findBySheetIdOrderByIdAsc(sheetId).forEach(w ->
                watched.computeIfAbsent(w.getUserName(), u -> new ArrayList<>()).add(w.getPersonId()));
        SheetState.Views views = new SheetState.Views(
                sheetPeople.stream().map(p -> PersonView.of(p, sheet.getToday())).toList(),
                sheetClaims.stream().map(ClaimView::of).map(SheetHistory::unlocked).toList(),
                sheetRates.stream().sorted(Comparator.comparing(Rate::getGrade).thenComparing(Rate.BY_FROM))
                        .map(RateView::of).toList(),
                periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().map(PeriodView::of).toList(),
                StatementService.summarize(statements.findBySheetIdOrderByIdAsc(sheetId)).stream()
                        .map(SummaryView::of).toList(),
                patrons.findBySheetIdOrderByIdAsc(sheetId).stream().map(PatronView::of).toList(),
                watched,
                roles.findBySheetIdOrderByUserName(sheetId).stream().map(RoleView::of).toList(),
                delegations.findBySheetIdOrderByIdAsc(sheetId).stream().map(DelegationView::of).toList(),
                holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(HolidayView::of).toList());
        SheetState state = SheetState.of(sheet, sheetRates, sheetPeople, sheetClaims, views);
        snapshots.deleteBySheetIdAndAsOf(sheetId, sheet.getToday());
        snapshots.saveAndFlush(new SheetSnapshot(sheetId, sheet.getToday(), json.writeValueAsString(state)));
    }

    /** The sheet as it stood at the end of a date; empty when no change was made on it by then. */
    @Transactional(readOnly = true)
    public Optional<SheetState> asOf(String sheetId, LocalDate date) {
        return snapshots.findFirstBySheetIdAndAsOfLessThanEqualOrderByAsOfDescIdDesc(sheetId, date)
                .map(s -> json.readValue(s.getState(), SheetState.class));
    }

    /** The claim as kept: no one's editor lock is part of what the sheet held. */
    private static ClaimView unlocked(ClaimView c) {
        return new ClaimView(c.id(), c.personId(), c.amount(), c.date(), c.note(), c.status(), c.number(),
                c.settledDue(), c.openedBy(), c.stated(), c.statedDue(), c.corrects(), c.dueBy(), c.deferredUntil(),
                c.log(), c.proofs(), c.splitFrom(), null, c.lateEntry(), c.remindedOn(), c.ref(), c.tags(),
                c.voidReason(), c.comments(), c.editedBy(), c.batch());
    }

    /** The lists the screen reads of the sheet as it stood at the end of a date; none when no change was made on it
     *  by then. */
    @Transactional(readOnly = true)
    public SheetState.Views viewsAsOf(String sheetId, LocalDate date) {
        return asOf(sheetId, date).map(SheetState::views).orElse(SheetState.Views.NONE);
    }

    /** The people as the screen read them at the end of a date, each with the grade in force on it. */
    @Transactional(readOnly = true)
    public List<PersonView> peopleAsOf(String sheetId, LocalDate date) {
        return asOf(sheetId, date).map(s -> s.people(sheetId, date)).orElse(List.of());
    }

    /** The sheet as it stood at the end of a date, unsaved, with that date standing in for its today: as it was
     *  started when no change was made on it by then. Its parent, not dated, is the one it names now. */
    @Transactional(readOnly = true)
    public Sheet sheetAsOf(Sheet live, LocalDate date) {
        return asOf(live.getId(), date).map(s -> s.rebuildSheet(live, date))
                .orElseGet(() -> {
                    Sheet started = new Sheet(live.getId(), live.getCreatedBy(), live.getCreatedAt(), date);
                    started.setParentId(live.getParentId());
                    return started;
                });
    }
